update_rule.pseudocode:
if not built:
  set RNG(seed=rng.seed)
  assign each agent to group in {majority, minority} by group.share_minority
  if network.type == 'small_world':
    G = WattsStrogatz(population.size, k=round(network.avg_degree), p=network.rewiring_prob)
  elif network.type == 'scale_free':
    G = BarabasiAlbert(population.size, m=max(1, round(network.avg_degree/2)), exponent=degree.exponent_scale_free)
  else:
    G = ErdosRenyi(population.size, p=network.avg_degree/(population.size-1))
  apply homophily: rewire fraction network.homophily_strength of cross-group edges to within-group where possible
  if network.assortativity_on_threshold:
    assort nodes so similar thresholds are more connected (degree-preserving swap)
  draw thresholds ~ TruncatedNormal(mean=influence.threshold_mean, std=influence.threshold_std, [0,1])
  draw susceptibility ~ Beta(alpha=influence.susceptibility_shape, beta=influence.susceptibility_shape)
  set credulity_i = misinformation.credulity + Normal(0, 0.05) clipped to [0,1]
  initialize adopted_i ~ Bernoulli(initial.adoption_fraction)
  initialize belief_score_i = 1.0 if adopted_i else 0.0
  output signal.network=G and signal.agent_state_init={attributes per agent}
  built = True
